import{_ as i,r as t,o,c as r,e as s,a as p,s as c}from"./chunks/framework.CXcwiNg-.js";const z=JSON.parse('{"title":"|resize - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[],"relativePath":"1.x/markup/filter-resize.md","filePath":"1.x/markup/filter-resize.md"}'),l={name:"1.x/markup/filter-resize.md"};function u(d,e,h,g,m,f){const a=t("pre-heading"),n=t("post-heading");return o(),r("div",null,[s(a),e[0]||(e[0]=p("h1",null,"|resize",-1)),s(n),e[1]||(e[1]=c(`<p>The <code>|resize</code> filter attempts to resize the provided image source using the provided resizing configuration and outputs a URL to the resized image.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media<span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">1920</span><span class="token punctuation">,</span> <span class="token number">1080</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>If the filter can successfully resize the provided image, then a URL to the October image resizer (<code>/resize/$id/$targetUrl</code>) will be rendered as the output of this filter until the image has been successfully resized. Once the image has been resized any future calls to this filter with the specific image and configuration combination will instead output a direct URL to the resized image.</p><p>This means that the actual work of resizing the image is delayed until the browser requests a specific image which prevents the resizing of the images from blocking the rendering of a page. It also means that several resize requests can be handled at once in parallel as the browser will make multiple requests at the same time for resized images with each request able to handle just resizing its own image.</p><blockquote><p><strong>Note</strong>: If the filter is unable to process the provided image, then it will instead return the original URL unmodified.</p></blockquote><p>The filter accepts three parameters: <code>|resize(int $width [, int $height , array $options])</code>.</p><p>See the <a href="./../services/image-resizing.html#resize-parameters">image resizing docs</a> for more information on the parameters.</p><ul><li><a href="./../services/image-resizing.html#resize-sources">List of locations images can be resized from</a></li></ul><blockquote><p><strong>Note</strong>: The image resizing functionality requires a cache driver that persists cache data between requests in order to function, <code>array</code> is not a supported cache driver if you wish to use this functionality.</p></blockquote>`,9))])}const _=i(l,[["render",u]]);export{z as __pageData,_ as default};
